function renderTrackingSummary(){document.querySelector('#summary-watched').textContent=watched.size;document.querySelector('#summary-favorites').textContent=favorites.size;document.querySelector('#summary-catalog').textContent=movies.length}
function openSummaryFilter(filter){favoritesOnly=filter==='favorites';watchedOnly=filter==='watched';folderFilter=null;activeCategory='Todos';typeFilter='Todos';query='';search.value='';catalogPage=1;renderFilters();render();document.querySelector('#catalogo').scrollIntoView({behavior:'smooth',block:'start'})}
window.addEventListener('DOMContentLoaded',renderTrackingSummary);
document.addEventListener('click',event=>{const summary=event.target.closest('[data-summary-filter]');if(summary){openSummaryFilter(summary.dataset.summaryFilter);return}if(event.target.closest('[data-watched],[data-favorite]'))renderTrackingSummary()});
