function addChatMessage(role,text){const row=document.createElement('div');row.className=`chat-turn ${role}-turn`;if(role==='assistant'){const avatar=document.createElement('span');avatar.className='chat-avatar';avatar.setAttribute('aria-hidden','true');avatar.textContent='✦';row.append(avatar)}const bubble=document.createElement('div');bubble.className='chat-bubble';bubble.textContent=text;row.append(bubble);document.querySelector('#recommend-results').append(row)}
function recommend(message){const input=document.querySelector('#recommend-input');const text=(message??input.value).trim();if(!text)return;addChatMessage('user',text);input.value='';document.querySelector('#chat-suggestions').classList.add('is-hidden');const normalized=text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');const terms=[['acao',['acao','aventura']],['comedia',['comedia','engracado','leve']],['ficcao',['ficcao cientifica','ciencia ficcao','sci-fi','sci fi']],['terror',['terror','assustador','suspense']],['romance',['romance','romantico','romantica']],['anime',['anime','animes']],['serie',['serie','series']],['classico',['classico','classicos']]];const genreValues={acao:'Ação',comedia:'Comédia',ficcao:'Ficção Científica',terror:'Terror',romance:'Romance',anime:'Animes',serie:'Séries',classico:'Clássicos'};const taste=new Set(terms.filter(([,words])=>words.some(word=>normalized.includes(word))).map(([key])=>genreValues[key]));let profile={};try{profile=JSON.parse(localStorage.getItem('filmes-perfil')||'{}')}catch{};if(!taste.size)(profile.genres||[]).forEach(genre=>taste.add(genre));for(const movie of movies.filter(item=>favorites.has(item.id)))movie.categories.forEach(category=>taste.add(category));const wantsSeries=/\bserie(s)?\b/.test(normalized);const wantsAnime=/\banime(s)?\b/.test(normalized);const wantsFilm=/\bfilme(s)?\b|\bmovie(s)?\b/.test(normalized);const pool=movies.filter(movie=>!favorites.has(movie.id)&&(!wantsSeries||movie.type==='Série'||movie.categories.includes('Séries'))&&(!wantsAnime||movie.type==='Anime')&&(!wantsFilm||movie.type==='Filme'));const source=pool.length?pool:movies.filter(movie=>!favorites.has(movie.id));const ranked=source.map(movie=>({movie,score:movie.categories.filter(category=>taste.has(category)).length})).sort((a,b)=>b.score-a.score||Number(b.movie.year)-Number(a.movie.year));const matched=ranked.filter(item=>item.score>0);const picks=(matched.length?matched:ranked).slice(0,3);const response=matched.length?'Separei estas opções do catálogo que combinam com o que você pediu:':`Encontrei estas opções no catálogo para você explorar:`;addChatMessage('assistant',response);const cards=document.createElement('div');cards.className='chat-recommendations';cards.innerHTML=picks.map(({movie})=>`<article class="recommend-card" data-recommend="${movie.id}" tabindex="0" role="button" aria-label="Ver detalhes de ${movie.title}"><img src="${movie.poster}" alt="Pôster de ${movie.title}" onerror="this.onerror=null;this.src='https://placehold.co/160x240/202231/f3a75a?text=Filmes'"><div><strong>${movie.title}</strong><span>${movie.type} · ${movie.year} · ★ ${movie.rating}</span></div></article>`).join('');document.querySelector('#recommend-results').append(cards);document.querySelector('#recommend-results').scrollTop=document.querySelector('#recommend-results').scrollHeight}
function render(){renderFolderBar();renderTypePages();renderLanguageFilter();const filtered=movies.filter(m=>(languageFilter==='Todos'||m.language===languageFilter)&&(typeFilter==='Todos'||(typeFilter==='Filmes'?(m.type==='Filme'||m.mediaType==='movie'):typeFilter==='Séries'?m.type==='Série':typeFilter==='Animes'?(m.type==='Anime'||m.categories.includes('Animes')):typeFilter==='Novelas'?m.type==='Novela':typeFilter==='Doramas'?m.type==='Dorama':m.type===typeFilter))&&(!folderFilter||(movieFolders[m.id]||[]).includes(folderFilter))&&(activeCategory==='Todos'||m.categories.includes(activeCategory))&&(!favoritesOnly||favorites.has(m.id))&&(!watchedOnly||watched.has(m.id))&&(!query||`${m.title} ${m.year} ${m.categories.join(' ')}`.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))));const pages=Math.max(1,Math.ceil(filtered.length/pageSize));catalogPage=Math.min(catalogPage,pages);const visible=filtered.slice((catalogPage-1)*pageSize,catalogPage*pageSize);renderPagination(filtered.length);grid.innerHTML=visible.map(m=>`<article class="movie-card" data-id="${m.id}" tabindex="0" aria-label="Ver detalhes de ${m.title}"><div class="poster-wrap"><img src="${m.poster}" alt="Pôster de ${m.title}" loading="lazy" onerror="this.src='https://placehold.co/500x750/202231/f3a75a?text=Filmes'"><span class="poster-rating"><b>★</b> ${m.rating==='—'?'':m.rating}</span><button class="favorite-button ${favorites.has(m.id)?'is-favorite':''}" data-favorite="${m.id}" aria-label="${favorites.has(m.id)?'Remover da biblioteca':'Adicionar à biblioteca'}" aria-pressed="${favorites.has(m.id)}">${favorites.has(m.id)?'♥':'♡'}</button><button class="watched-button ${watched.has(m.id)?'is-watched':''}" data-watched="${m.id}" aria-label="${watched.has(m.id)?'Marcar como não assistido':'Marcar como já assistido'}" aria-pressed="${watched.has(m.id)}">${watched.has(m.id)?'✓ Já assisti':'+ Já assisti'}</button></div><span class="card-category">${m.categories[0]}</span><h3>${m.title}</h3><div class="card-meta">${m.year} <span>·</span> ${m.type}</div></article>`).join('');empty.hidden=visible.length>0;count.textContent=`${filtered.length} ${filtered.length===1?'título':'títulos'}${favoritesOnly?' na biblioteca':''}${watchedOnly?' já assistidos':''}`;document.querySelectorAll('.fav-count').forEach(x=>x.textContent=favorites.size);favToggle.setAttribute('aria-pressed',favoritesOnly);favToggle.querySelector('span').textContent=favoritesOnly?'Ver catálogo':'Favoritos';document.querySelector('#watched-toggle').setAttribute('aria-pressed',watchedOnly);document.querySelector('#watched-toggle span').textContent=watchedOnly?'Ver catálogo':'Minha biblioteca';document.querySelector('#section-title').textContent=folderFilter?(folders.find(f=>f.id===folderFilter)?.name||'Pasta'):watchedOnly?'Minha biblioteca':favoritesOnly?'Favoritos':'Explore o catálogo';document.querySelector('#section-eyebrow').textContent=folderFilter?'SUA PASTA':watchedOnly?'SUA BIBLIOTECA':favoritesOnly?'SEUS FAVORITOS':'ESCOLHA SUA PRÓXIMA SESSÃO';if((favoritesOnly||watchedOnly)&&visible.length===0&&!query){empty.querySelector('span').textContent=watchedOnly?'✓':'▣';empty.querySelector('h3').textContent=watchedOnly?'Sua biblioteca está vazia':'Você ainda não tem favoritos';empty.querySelector('p').textContent=watchedOnly?'Marque filmes, séries ou animes como assistidos para encontrá-los aqui.':'Toque no coração de um título para guardá-lo aqui.'}else{empty.querySelector('span').textContent='⌕';empty.querySelector('h3').textContent='Nenhum título encontrado';empty.querySelector('p').textContent='Tente outra busca ou escolha uma categoria diferente.'}}
