let featureMode='new',featureIndex=0;
function featuredTitles(){const available=featureMode==='new'?movies:movies.filter(m=>Number.isFinite(Number(m.rating)));return [...available].sort((a,b)=>featureMode==='new'?Number(b.year)-Number(a.year):Number(b.rating)-Number(a.rating))}
function renderFeature(){const list=featuredTitles();if(!list.length)return;featureIndex=((featureIndex%list.length)+list.length)%list.length;const item=list[featureIndex];document.querySelector('#hero-feature-backdrop').style.backgroundImage=`url("${item.poster}")`;const poster=document.querySelector('#hero-feature-poster');poster.src=item.poster;poster.alt=`Pôster de ${item.title}`;document.querySelector('#hero-feature-kicker').textContent=featureMode==='new'?'NOVIDADE':'EM ALTA';document.querySelector('#hero-feature-title').textContent=item.title;document.querySelector('#hero-feature-meta').textContent=`${item.type} · ${item.year} · ★ ${item.rating}`;document.querySelector('#hero-feature-position').textContent=`${featureIndex+1} / ${list.length}`;
const cloudTrackedKeys=['filmes-favoritos','filmes-assistidos','filmes-pastas','filmes-pastas-titulos','filmes-perfil','filmes-streamings'];let cloudClient=null,cloudConflict=null;
function markCloudDirty(){localStorage.setItem('filmes-nuvem-modified',String(Date.now()))}
function cloudMessage(message,isError=false){const status=document.querySelector('#cloud-status');status.textContent=message;status.classList.toggle('is-error',isError);const profileStatus=document.querySelector('#profile-cloud-status');if(profileStatus){profileStatus.textContent=message;profileStatus.classList.toggle('is-error',isError)}}
const defaultCloudProjectUrl='https://wghhyyfpsuujcgmuwefu.supabase.co';
function readCloudConfig(){try{const config=JSON.parse(localStorage.getItem('filmes-nuvem-config')||'{}');return {...config,url:config.url||defaultCloudProjectUrl}}catch{return {url:defaultCloudProjectUrl}}}
function ensureCloudClient(){const url=document.querySelector('#cloud-url').value.trim()||readCloudConfig().url;const key=document.querySelector('#cloud-key').value.trim()||readCloudConfig().key;if(!url||!key){cloudMessage('Preencha e salve a URL e a chave pública do projeto.',true);return null}if(!window.supabase?.createClient){cloudMessage('Não foi possível carregar a conexão de nuvem. Verifique a internet e tente novamente.',true);return null}if(!cloudClient)cloudClient=window.supabase.createClient(url,key);return cloudClient}
function saveCloudConfig(){const url=document.querySelector('#cloud-url').value.trim(),key=document.querySelector('#cloud-key').value.trim();if(!/^https:\/\//.test(url)||!key){cloudMessage('Informe a URL HTTPS e a chave pública do projeto.',true);return}localStorage.setItem('filmes-nuvem-config',JSON.stringify({url,key}));cloudClient=null;cloudMessage('Conexão salva neste dispositivo. Agora entre ou crie sua conta.')}
function openCloud(){const config=readCloudConfig();document.querySelector('#cloud-url').value=config.url||defaultCloudProjectUrl;document.querySelector('#cloud-key').value=config.key||'';document.querySelector('#cloud-modal').showModal();const client=config.key?ensureCloudClient():null;if(client)client.auth.getSession().then(({data})=>{if(data.session){cloudMessage('Conectado como '+data.session.user.email+'.');document.querySelector('#cloud-signout').hidden=false}else cloudMessage('Cole a chave pública do projeto e salve para ativar a conexão.')});else cloudMessage('O endereço do projeto já está preenchido. Cole a chave pública para ativar a conexão.')}
async function cloudAuth(mode,profileCredentials=null){const client=ensureCloudClient();if(!client)return false;const email=(profileCredentials?.email??document.querySelector('#cloud-email').value).trim(),password=profileCredentials?.password??document.querySelector('#cloud-password').value;if(!email||!password){cloudMessage('Preencha seu e-mail e sua senha.',true);return false}cloudMessage(mode==='signup'?'Criando sua conta…':'Entrando…');const result=mode==='signup'?await client.auth.signUp({email,password}):await client.auth.signInWithPassword({email,password});if(result.error){cloudMessage(result.error.message,true);return false}document.querySelector('#cloud-signout').hidden=false;if(mode==='signup'&&!result.data.session){cloudMessage('Conta criada. Confirme o e-mail; depois, entre com o mesmo e-mail e senha neste aparelho e nos demais.');return false}if(profileCredentials?.autoSync){cloudMessage('Conta conectada. Sincronizando sua biblioteca…');await syncCloudData()}else cloudMessage('Conectado como '+email+'. Toque em “Sincronizar agora” para sincronizar os dados existentes.');return true}

async function saveProfileToCloud(profile,hasPendingLocalChanges=false){const config=readCloudConfig();if(!config.url||!config.key||!window.supabase?.createClient){document.querySelector('#profile-saved').textContent='Perfil salvo neste aparelho. Conecte sua conta em Nuvem para salvá-lo automaticamente entre dispositivos.';return}try{const client=cloudClient||window.supabase.createClient(config.url,config.key);cloudClient=client;const {data:auth,error:authError}=await client.auth.getUser();if(authError||!auth.user){document.querySelector('#profile-saved').textContent='Perfil salvo neste aparelho. Entre em Nuvem para salvá-lo automaticamente.';return}const {data:remote,error}=await client.from('filmes_user_data').select('payload').eq('user_id',auth.user.id).maybeSingle();if(error)throw error;const payload={...(remote?.payload||collectCloudData()),'filmes-perfil':JSON.stringify(profile)};const saved=await client.from('filmes_user_data').upsert({user_id:auth.user.id,payload,updated_at:new Date().toISOString()},{onConflict:'user_id'}).select('updated_at').single();if(saved.error)throw saved.error;localStorage.setItem('filmes-nuvem-baseline',saved.data.updated_at);if(!hasPendingLocalChanges){const now=String(Date.now());localStorage.setItem('filmes-nuvem-last-sync',now);localStorage.setItem('filmes-nuvem-modified',now)}document.querySelector('#profile-saved').textContent='Perfil salvo neste aparelho e na nuvem.'}catch(error){document.querySelector('#profile-saved').textContent='Perfil salvo neste aparelho. Não foi possível atualizar a nuvem: '+(error.message||'tente novamente')}}
function collectCloudData(){return Object.fromEntries(cloudTrackedKeys.map(key=>[key,localStorage.getItem(key)]))}
function hasLocalCloudData(){return cloudTrackedKeys.some(key=>{const value=localStorage.getItem(key);return value&&value!=='[]'&&value!=='{}'})}
async function uploadCloudData(client,userId){const result=await client.from('filmes_user_data').upsert({user_id:userId,payload:collectCloudData(),updated_at:new Date().toISOString()},{onConflict:'user_id'}).select('updated_at').single();if(result.error)throw result.error;localStorage.setItem('filmes-nuvem-baseline',result.data.updated_at);const now=String(Date.now());localStorage.setItem('filmes-nuvem-last-sync',now);localStorage.setItem('filmes-nuvem-modified',now);return result.data.updated_at}
function applyCloudData(payload,updatedAt){for(const key of cloudTrackedKeys){if(payload[key]===null||payload[key]===undefined)localStorage.removeItem(key);else localStorage.setItem(key,payload[key])}localStorage.setItem('filmes-nuvem-baseline',updatedAt);const now=String(Date.now());localStorage.setItem('filmes-nuvem-last-sync',now);localStorage.setItem('filmes-nuvem-modified',now);document.querySelector('#cloud-conflict-actions').hidden=true}
async function syncCloudData(){const client=ensureCloudClient();if(!client)return;cloudMessage('Verificando seus dados…');const {data:auth,error:authError}=await client.auth.getUser();if(authError||!auth.user){cloudMessage('Entre na sua conta antes de sincronizar.',true);return}try{const {data:remote,error}=await client.from('filmes_user_data').select('payload,updated_at').eq('user_id',auth.user.id).maybeSingle();if(error)throw error;if(!remote){await uploadCloudData(client,auth.user.id);cloudMessage('Sua biblioteca e seu perfil foram salvos na nuvem.');return}const baseline=localStorage.getItem('filmes-nuvem-baseline'),lastSync=Number(localStorage.getItem('filmes-nuvem-last-sync')||0),localUpdated=Number(localStorage.getItem('filmes-nuvem-modified')||0),localDirty=baseline?localUpdated>lastSync:hasLocalCloudData(),remoteDirty=baseline?Date.parse(remote.updated_at)>Date.parse(baseline):false;if(!baseline&&!hasLocalCloudData()){applyCloudData(remote.payload||{},remote.updated_at);cloudMessage('Perfil e biblioteca recebidos da nuvem. Atualizando…');setTimeout(()=>location.reload(),700);return}if(!baseline&&hasLocalCloudData()){cloudConflict={client,userId:auth.user.id,remote};document.querySelector('#cloud-conflict-actions').hidden=false;document.querySelector('#cloud-modal').showModal();cloudMessage('Encontramos dados neste aparelho e na nuvem. Escolha qual versão usar.');return}if(localDirty&&remoteDirty){cloudConflict={client,userId:auth.user.id,remote};document.querySelector('#cloud-conflict-actions').hidden=false;document.querySelector('#cloud-modal').showModal();cloudMessage('Há alterações dos dois lados. Escolha qual versão manter.');return}if(localDirty){await uploadCloudData(client,auth.user.id);cloudMessage('Nuvem atualizada com os dados deste aparelho.')}else if(remoteDirty){applyCloudData(remote.payload||{},remote.updated_at);cloudMessage('Dados recebidos da nuvem. Atualizando a biblioteca…');setTimeout(()=>location.reload(),700)}else{localStorage.setItem('filmes-nuvem-baseline',remote.updated_at);localStorage.setItem('filmes-nuvem-last-sync',String(Date.now()));cloudMessage('Sua biblioteca já está sincronizada.')}}catch(error){cloudMessage(error.message||'Não foi possível sincronizar. Confira a tabela e as políticas do banco.',true)}}
async function chooseCloudVersion(useLocal){if(!cloudConflict)return;const conflict=cloudConflict;cloudConflict=null;document.querySelector('#cloud-conflict-actions').hidden=true;try{if(useLocal){await uploadCloudData(conflict.client,conflict.userId);cloudMessage('Nuvem atualizada com a versão deste aparelho.')}else{applyCloudData(conflict.remote.payload||{},conflict.remote.updated_at);cloudMessage('Versão da nuvem recebida. Atualizando…');setTimeout(()=>location.reload(),700)}}catch(error){cloudMessage(error.message||'Não foi possível aplicar essa versão.',true)}}
document.querySelector('#cloud-open').addEventListener('click',openCloud);document.querySelector('#cloud-close').addEventListener('click',()=>document.querySelector('#cloud-modal').close());document.querySelector('#cloud-modal').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});document.querySelector('#cloud-save-config').addEventListener('click',saveCloudConfig);document.querySelector('#cloud-signin').addEventListener('click',()=>cloudAuth('signin'));document.querySelector('#cloud-signup').addEventListener('click',()=>cloudAuth('signup'));document.querySelector('#cloud-sync').addEventListener('click',syncCloudData);document.querySelector('#cloud-use-local').addEventListener('click',()=>chooseCloudVersion(true));document.querySelector('#cloud-use-remote').addEventListener('click',()=>chooseCloudVersion(false));document.querySelector('#cloud-signout').addEventListener('click',async()=>{const client=ensureCloudClient();if(!client)return;await client.auth.signOut();document.querySelector('#cloud-signout').hidden=true;cloudMessage('Você saiu da conta. Seus dados locais continuam neste dispositivo.')});
document.querySelectorAll('[data-feature-mode]').forEach(button=>button.classList.toggle('active',button.dataset.featureMode===featureMode))}
function advanceFeature(direction=1){const hero=document.querySelector('.hero-showcase');hero.classList.remove('feature-shift');void hero.offsetWidth;featureIndex+=direction;renderFeature();hero.classList.add('feature-shift');window.setTimeout(()=>hero.classList.remove('feature-shift'),500)}document.querySelectorAll('[data-feature-mode]').forEach(button=>button.addEventListener('click',()=>{featureMode=button.dataset.featureMode;featureIndex=0;renderFeature()}));document.querySelector('#hero-feature-prev').addEventListener('click',()=>advanceFeature(-1));document.querySelector('#hero-feature-next').addEventListener('click',()=>advanceFeature(1));document.querySelector('#hero-feature-details').addEventListener('click',()=>{const item=featuredTitles()[featureIndex];if(item)openDetails(item.id)});renderFeature();window.setInterval(()=>advanceFeature(1),5000);
function setAiView(){const ai=location.hash==='#assistente-ia';const profile=location.hash==='#perfil';document.body.classList.toggle('ai-mode',ai);document.body.classList.toggle('profile-mode',profile)}document.querySelector('#ai-nav').addEventListener('click',()=>document.body.classList.add('ai-mode'));document.querySelector('#profile-nav').addEventListener('click',()=>document.body.classList.add('profile-mode'));document.querySelector('#explore-nav').addEventListener('click',()=>{document.body.classList.remove('ai-mode','profile-mode')});document.querySelector('[data-favorites-link]').addEventListener('click',()=>document.body.classList.remove('ai-mode','profile-mode'));window.addEventListener('hashchange',setAiView);setAiView();
const profileForm=document.querySelector('#profile-form');let savedProfile={};try{savedProfile=JSON.parse(localStorage.getItem('filmes-perfil')||'{}')}catch{};document.querySelector('#profile-name').value=savedProfile.name||'';document.querySelectorAll('#profile-form input[name="genre"]').forEach(input=>input.checked=(savedProfile.genres||[]).includes(input.value));function updateProfileAvatar(){const name=document.querySelector('#profile-name').value.trim();document.querySelector('#profile-avatar').textContent=(name||'Filmes').charAt(0).toLocaleUpperCase('pt-BR')}updateProfileAvatar();document.querySelector('#profile-name').addEventListener('input',updateProfileAvatar);profileForm.addEventListener('submit',event=>{event.preventDefault();const profile={name:document.querySelector('#profile-name').value.trim(),genres:[...document.querySelectorAll('#profile-form input[name="genre"]:checked')].map(input=>input.value)};const hasPendingLocalChanges=Number(localStorage.getItem('filmes-nuvem-modified')||0)>Number(localStorage.getItem('filmes-nuvem-last-sync')||0);localStorage.setItem('filmes-perfil',JSON.stringify(profile));markCloudDirty();document.querySelector('#profile-saved').textContent='Salvando perfil…';updateProfileAvatar();saveProfileToCloud(profile,hasPendingLocalChanges)});

